import re
import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(100000)

    token_re = re.compile(
        r"<=|>=|<>|[()+\-*/,:=<>]|\d+|[A-Z]\d+|SUM|MIN|MAX|IF"
    )
    asts = {}
    states = {}
    values = {}

    def parse_formula(text):
        tokens = []
        pos = 0
        while pos < len(text):
            if text[pos].isspace():
                pos += 1
                continue
            match = token_re.match(text, pos)
            tokens.append(match.group())
            pos = match.end()

        i = 0

        def peek(offset=0):
            return tokens[i + offset] if i + offset < len(tokens) else None

        def take(expected=None):
            nonlocal i
            token = tokens[i]
            if expected is not None:
                assert token == expected
            i += 1
            return token

        def parse_expr():
            return parse_add()

        def parse_add():
            node = parse_mul()
            while peek() in ("+", "-"):
                op = take()
                node = ("bin", op, node, parse_mul())
            return node

        def parse_mul():
            node = parse_unary()
            while peek() in ("*", "/"):
                op = take()
                node = ("bin", op, node, parse_unary())
            return node

        def parse_unary():
            if peek() == "-":
                take("-")
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom():
            token = peek()

            if token == "(":
                take("(")
                node = parse_expr()
                take(")")
                return node

            if token in ("SUM", "MIN", "MAX"):
                name = take()
                take("(")
                args = []

                while True:
                    if (
                        peek() is not None
                        and re.fullmatch(r"[A-Z]\d+", peek())
                        and peek(1) == ":"
                    ):
                        start = take()
                        take(":")
                        end = take()
                        args.append(("range", start, end))
                    else:
                        args.append(("expr", parse_expr()))

                    if peek() != ",":
                        break
                    take(",")

                take(")")
                return ("fun", name, args)

            if token == "IF":
                take("IF")
                take("(")
                left = parse_expr()
                op = take()
                right = parse_expr()
                take(",")
                yes = parse_expr()
                take(",")
                no = parse_expr()
                take(")")
                return ("if", op, left, right, yes, no)

            token = take()
            if token.isdigit():
                return ("num", int(token))
            return ("cell", token)

        return parse_expr()

    def is_error(value):
        return isinstance(value, str)

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def eval_cell(name):
        if name not in cells:
            return 0

        state = states.get(name, 0)
        if state == 2:
            return values[name]
        if state == 1:
            return "#CYCLE!"

        states[name] = 1
        content = cells[name].strip()

        if not content.startswith("="):
            result = int(content)
        else:
            if name not in asts:
                asts[name] = parse_formula(content[1:])
            result = eval_node(asts[name])

        values[name] = result
        states[name] = 2
        return result

    def eval_node(node):
        kind = node[0]

        if kind == "num":
            return node[1]

        if kind == "cell":
            return eval_cell(node[1])

        if kind == "neg":
            value = eval_node(node[1])
            return value if is_error(value) else -value

        if kind == "bin":
            _, op, left_node, right_node = node
            left = eval_node(left_node)
            if is_error(left):
                return left

            right = eval_node(right_node)
            if is_error(right):
                return right

            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            return trunc_div(left, right)

        if kind == "if":
            _, op, left_node, right_node, yes_node, no_node = node
            left = eval_node(left_node)
            if is_error(left):
                return left

            right = eval_node(right_node)
            if is_error(right):
                return right

            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right

            return eval_node(yes_node if condition else no_node)

        _, name, args = node
        seen = False
        total = 0
        best = None

        def add_value(value):
            nonlocal seen, total, best
            seen = True
            if name == "SUM":
                total += value
            elif best is None or (name == "MIN" and value < best) or (
                name == "MAX" and value > best
            ):
                best = value

        for arg in args:
            if arg[0] == "expr":
                value = eval_node(arg[1])
                if is_error(value):
                    return value
                add_value(value)
            else:
                _, start, end = arg
                c1, r1 = ord(start[0]) - 65, int(start[1:])
                c2, r2 = ord(end[0]) - 65, int(end[1:])

                for row in range(min(r1, r2), max(r1, r2) + 1):
                    for col in range(min(c1, c2), max(c1, c2) + 1):
                        cell = chr(65 + col) + str(row)
                        if cell in cells:
                            value = eval_cell(cell)
                            if is_error(value):
                                return value
                            add_value(value)

        if name == "SUM":
            return total
        return best if seen else 0

    return {name: eval_cell(name) for name in cells}
